page.script:
// 触发事件
function CrrHandler(t) {
	// 保存&更新事件
	if (t.id == "save") {
		var formpanel = Ext.getCmp("productPriceForm").getForm();
		if (formpanel.isValidCux()) {
			var gridpanel = Ext.getCmp("productPriceItemList");
			var gridpanelData = gridpanel.getStore().getData();
			if (gridpanel.operateArray.length === 0 && gridpanelData.length === 0) {
				Ext.MessageBox.alert("提示", "请参选产品定价明细！");
				return false;
			}
			var data = formpanel.getValues();
			if (gridpanel.operateArray.length > 0) {
				var newData = [];
				for(var i = 0; i < gridpanel.operateArray.length; i++) {
					var d = gridpanel.operateArray[i];
					if (isNull(d.taxPrice)) {
						Ext.MessageBox.alert("提示", "第" + (i+1) + "行，含税单价不能为空！");
						return false;
					}
					if (isNull(d.depotName)) {
						Ext.MessageBox.alert("提示", "第" + (i+1) + "行，仓库名称不能为空！");
						return false;
					}
				}
			}
			data.itemAddList = gridpanel.operateArray;
			var url = "/webapi/marketing/productPrice/add";
			if (data.id != null && data.id != "") {
				url = "/webapi/marketing/productPrice/edit";
			}
			post(url, data, function(res) {
				Ext.MessageBox.alert("提示", res.msg);
				Ext.getCmp('productPriceListNew').getStore().load();
				Ext.getCmp('productPriceFormWin').close();
			});
		}
	}
	// 明细新增事件
	if (t.id == "itemNew") {
		var data = {confirm: "priceSchemeItemfirm"};
		handleRoute("ChoosePriceSchemeItem", data);
	}
	// 明细删除事件
	if (t.id == "itemDelete") {
		var records = Ext.getCmp("productPriceItemList").getSelectionModel().getSelection();
		if (records.length < 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行删除!");
			return false;
		}
		handleDelConfirm("/webapi/marketing/productPrice/item/delete", records, Ext.getCmp("productPriceItemList"));
	}
}
// 产品档案列表
function chooseMateriel(data) {
	var data = {confirm: "materielConfirm"};
	handleRoute("ChooseMateriel", data);
}
// 产品档案确定事件
function materielConfirm(data) {
	var form = Ext.getCmp("productPriceForm").getForm();
	form.findField("materielNo").setValue(data.materielNo);
	form.findField("materielName").setValue(data.materielName);
	form.findField("skuNo").setValue(data.skuNo);
	form.findField("skuName").setValue(data.skuName);
	form.findField("productClassNo").setValue(data.productClassNo);
	form.findField("productClassName").setValue(data.productClassName);
}
// 仓库档案列表
function chooseDepot() {
	var data = {confirm: "singleDepotConfirm"};
	handleRoute("ChooseSingleDepot", data);
}
// 仓库档案确定事件
function singleDepotConfirm(data) {
	Ext.getCmp("editor_productPriceItemList_depotNo").setValue(data.depotNo);
	Ext.getCmp("editor_productPriceItemList_depotName").setValue(data.depotName);
}
// 定价方案明细确认事件
function priceSchemeItemfirm(data) {
	var newData = [];
	for(var i = 0; i < data.length; i++) {
		var obj = {
			schemeNo: data[i].data.schemeNo,
			schemeItemNo: data[i].data.schemeItemNo,
			areaNo: data[i].data.areaNo,
			areaName: data[i].data.areaName,
			deliveryPlaceNo: data[i].data.deliveryPlaceNo,
			deliveryPlaceName: data[i].data.deliveryPlaceName,
			deliveryPlaceClassNo: data[i].data.deliveryPlaceClassNo,
			deliveryPlaceClassName: data[i].data.deliveryPlaceClassName,
			distributionWay: data[i].data.distributionWay,
			transportWay: data[i].data.transportWay,
			payWay: data[i].data.payWay,
			currencyUnit: "CNY" == data[i].data.currency ? "YMT" : "MYMT",
			productPriceItemNo : Ext.getCmp("productPriceForm").getForm().findField("productPriceNo").getValue() + 
				(i + 1).toString().padStart(4, '0')
		}
		newData.push(obj);
	}
	setArrayData(Ext.getCmp('productPriceItemList'), newData);
	Ext.getCmp('productPriceItemList').getStore().load();
}
// 重写加载事件
Ext.getCmp('productPriceItemList').getStore().on('load', function(store) {
	var panel = Ext.getCmp('productPriceItemList');
	store.add(panel.operateArray);
	panel.down('pagingtoolbarcustom').updatePagingInfo(store.getCount(), store.pageSize);
});
// 进行修改
Ext.getCmp('productPriceItemList').on('edit', function(editor, e) {
	if (!e.newValues.id.includes("productPriceItemListModel")) {
		var url = "/webapi/marketing/productPrice/item/edit";
		post(url, e.newValues, function(res) {
			Ext.MessageBox.alert("提示", res.msg);
			Ext.getCmp('productPriceItemList').getStore().load();
		});
	}
});
